import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../providers/connection_provider.dart';
class HotspotScreen extends ConsumerWidget{const HotspotScreen({super.key});@override Widget build(BuildContext c,WidgetRef ref)=>FutureBuilder<List<dynamic>>(future:ref.read(mikrotikProvider).hotspot(),builder:(c,s)=>ListView(padding:const EdgeInsets.all(16),children:[Text('مستخدمو Hotspot',style:Theme.of(c).textTheme.headlineSmall),if(s.hasError)Text('تعذر التحميل: ${s.error}'),if(s.connectionState==ConnectionState.waiting)const LinearProgressIndicator(),if(s.hasData)for(final x in s.data!)ListTile(leading:const Icon(Icons.wifi),title:Text('${x['name']??'—'}'),subtitle:Text('${x['profile']??'default'}'))]));}
